using std::cin;
using std::cout;
using std::endl;

struct Student
{
    char  szName[32];
    int   iKorean;
    int   iEnglish;
    int   iMath;
    int   iTotal;
    float fAverage;
};

int main()
{
    Student tStudent = {};

    cout << "이름: ";
    cin.getline(tStudent.szName, 32);

    cout << "국어: ";
    cin >> tStudent.iKorean;

    cout << "영어: ";
    cin >> tStudent.iEnglish;

    cout << "수학: ";
    cin >> tStudent.iMath;

    tStudent.iTotal = tStudent.iKorean + tStudent.iEnglish + tStudent.iMath;
    tStudent.fAverage = tStudent.iTotal / 3.f;

    cout << "--- 성적표 ---" << endl;
    cout << "이름: " << tStudent.szName << endl;
    cout << "총점: " << tStudent.iTotal << endl;
    cout << "평균: " << tStudent.fAverage << endl;

    return 0;
}

