#include <iostream>
#include <cstring>

using std::cin;
using std::cout;
using std::endl;

struct Student
{
    char szName[32];
    int  iTotal;
    int  iRank;
};

int main()
{
    Student tStudentArray[3] = {};

    for (int i = 0; i < 3; i++)
    {
        cout << "이름: ";
        cin.getline(tStudentArray[i].szName, 32);

        cout << "총점: ";
        cin >> tStudentArray[i].iTotal;
        cin.ignore();
    }

    for (int i = 0; i < 3; i++)
    {
        tStudentArray[i].iRank = 1;
    }

    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            if (tStudentArray[i].iTotal < tStudentArray[j].iTotal)
                tStudentArray[i].iRank++;
        }
    }

    cout << "검색할 이름: ";
    char szInput[32] = {};
    cin.getline(szInput, 32);

    bool bFind = false;
    for (int i = 0; i < 3; i++)
    {
        if (strcmp(tStudentArray[i].szName, szInput) == 0)
        {
            cout << "이름: " << tStudentArray[i].szName << endl;
            cout << "총점: " << tStudentArray[i].iTotal << endl;
            cout << "석차: " << tStudentArray[i].iRank << endl;
            bFind = true;
            break;
        }
    }

    if (!bFind)
    {
        cout << szInput << " 학생의 정보가 존재하지 않습니다." << endl;
    }

    return 0;
}
